mapper.select:
select c1.c_name as cName, c1.c_Type as cType, c1.c_Creditcode as cCreditcode, c1.c_Contactperson as cContactperson, c1.c_Contactpersontel as cContactpersontel, c1.c_Unitlegalperson as cUnitlegalperson, mn.* from Contract_Permission_Company mn left join Sys_Company c1 on c1.c_id=mn.c_id
and mn.con_id=#{params.conId}
and c1.c_Type=#{params.cType}
and INSTR(c1.c_Creditcode,#{params.cCreditcode})
and INSTR(c1.c_Contactperson,#{params.cContactperson})
and INSTR(c1.c_Contactpersontel,#{params.cContactpersontel})
and INSTR(c1.c_Unitlegalperson,#{params.cUnitlegalperson})
and likeCname(#{params.cName},c1.C_Id)=true
and INSTR(c1.c_name,#{params.cName})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.cpc_sort asc
